from scipy.optimize import least_squares
L=np.log(eps)
def nm(f,p0,n=20):
    best=None
    rng=np.random.default_rng(0)
    for k in range(n):
        q=np.array(p0)*(1+0.5*rng.standard_normal(len(p0))) if k else np.array(p0,float)
        try:
            r=least_squares(lambda p: f(p)-sigma, q, max_nfev=3000)
            if best is None or r.cost<best.cost: best=r
        except Exception as e: pass
    return np.mean(best.fun**2)/np.var(sigma), best.x
